def select_demand(corpus_df):
    fallback_ids = ['n06-r07', 'n06-r08']
    threshold_mask = corpus_df.get('demand_score', 0) >= 3
    fallback_mask = corpus_df.get('record_id', '').isin(fallback_ids)
    support_mask = corpus_df.get('source_id', '').astype(str).str.len() > 0
    selected_df = corpus_df[(threshold_mask & support_mask) | fallback_mask]

    records = []
    for _, row in selected_df.iterrows():
        records.append({'record_id': row.get('record_id', ''), 'need': row.get('need', ''), 'demand_score': row.get('demand_score', 0), 'source_id': row.get('source_id', ''), 'source_weight': row.get('source_weight', 0)})

    present_ids = set(selected_df.get('record_id', []))
    for record_id in fallback_ids:
        if record_id not in present_ids:
            records.append({'record_id': record_id, 'need': '', 'demand_score': 0, 'source_id': '', 'source_weight': 0})

    return pd.DataFrame(records)
